const notes = [
  { id: 1, text: "Buy milk" },
  { id: 2, text: "Call the dentist" },
];

const $list = $("#notes").empty();

for (const note of notes) {
  $("<li>", { text: note.text, "data-id": note.id })
    .addClass("note")
    .appendTo($list);
}

console.log($list.children().length, $list.find(".note").last().data("id"));

function loadNotes(url) {
  return $.getJSON(url)
    .done(function (notes) {
      console.log("loaded " + notes.length + " notes from " + url);
    })
    .fail(function (jqXHR, textStatus, errorThrown) {
      console.log("failed: " + jqXHR.status + " " + errorThrown + " for " + url);
    });
}

loadNotes("/notes.json").always(function () {
  loadNotes("/missing.json");
});

const query = new URLSearchParams(location.search).get("q") ?? "";

$("#results-title").html("Results for <b>" + query + "</b>");

$("#results-title").text("Results for ").append($("<b>").text(query));

const list = document.querySelector("#tasks");
const error = document.querySelector("#error");

async function deleteTask(item) {
  const response = await fetch(`/api/tasks/${item.dataset.id}`, { method: "DELETE" });
  if (!response.ok) {
    throw new Error(`HTTP ${response.status}`);
  }
}

list.addEventListener("click", async (event) => {
  const button = event.target.closest(".delete");
  if (!button) return;

  event.preventDefault();
  const item = button.closest("li");

  try {
    await deleteTask(item);
    item.remove();
  } catch {
    error.textContent = "Couldn't delete that task.";
    error.hidden = false;
  }
});
